9	import type { OutMessage } from './message.ts';
10	
11	export interface Transport {
12	  /** Доставить сообщение. Возвращает id отправки, присвоенный транспортом. */
13	  send(msg: OutMessage): string;
14	}
15	
16	/**
17	 * Памятный транспорт — стенд для тестов: всё «отправленное» лежит в `sent`, id выдаются
18	 * подряд от единицы. Счётчик свой на каждый экземпляр, чтобы тесты не зависели от порядка
19	 * запуска друг друга.
20	 */
21	export function memoryTransport(): Transport & { sent: OutMessage[] } {
22	  const sent: OutMessage[] = [];
23	  let nextId = 1;
24	  return {
25	    sent,
26	    send(msg: OutMessage): string {
27	      sent.push(msg);
28	      const id = `mem-${nextId}`;
29	      nextId += 1;
30	      return id;
31	    },
32	  };
33	}
