15	  it('enqueue накапливает, ничего не отправляя', () => {
16	    const box = createOutbox();
17	    box.enqueue({ to: 'anna@example.ru', text: 'Заказ собран' });
18	    box.enqueue({ to: 'boris@example.ru', text: 'Заказ выдан' });
19	    strictEqual(box.pending(), 2);
20	  });
21	
22	  it('drain отправляет накопленное в порядке постановки и опустошает очередь', () => {
23	    const box = createOutbox();
24	    const t = memoryTransport();
25	    box.enqueue({ to: 'anna@example.ru', text: 'Заказ собран' });
26	    box.enqueue({ to: 'boris@example.ru', text: 'Заказ выдан' });
27	    const ids = box.drain(t);
28	    deepStrictEqual(ids, ['mem-1', 'mem-2']);
29	    deepStrictEqual(
30	      t.sent.map((m) => m.to),
31	      ['anna@example.ru', 'boris@example.ru'],
32	    );
33	    strictEqual(box.pending(), 0);
34	  });
35	
36	  it('drain пустой очереди ничего не отправляет', () => {
37	    const box = createOutbox();
38	    const t = memoryTransport();
39	    deepStrictEqual(box.drain(t), []);
40	    strictEqual(t.sent.length, 0);
41	  });
