1	/**
2	 * Отправитель.
3	 *
4	 * Тонкая обёртка над транспортом: одна точка, через которую уходит каждое уведомление.
5	 * Она нужна не ради строки кода, а ради места — правила отправки, когда появятся, встанут
6	 * сюда, а не размажутся по вызывающим.
7	 */
8	
9	import type { OutMessage } from './message.ts';
10	import type { Transport } from './transport.ts';
11	
12	/** Отправить одно уведомление. Возвращает id отправки, выданный транспортом. */
13	export function sendNotification(transport: Transport, msg: OutMessage): { id: string } {
14	  return { id: transport.send(msg) };
15	}
16

