2	 * Тесты отправителя.
3	 *
4	 * Отправка без опций: уведомление доходит до транспорта как есть, id — тот, что выдал
5	 * транспорт. Вызовы здесь намеренно без ключей, приоритетов и прочих опций — это контракт
6	 * «как было», и он обязан остаться законным.
7	 */
8	
9	import { deepStrictEqual, strictEqual } from 'node:assert/strict';
10	import { describe, it } from 'node:test';
11	
12	import { memoryTransport, sendNotification } from '../src/index.ts';
13	
14	describe('отправитель', () => {
