2	 * Публичный контракт пакета.
3	 *
4	 * Всё, что вызывают снаружи, проходит через этот файл. Внутренние модули друг на друга
5	 * ссылаются напрямую, но потребитель знает только отсюда.
6	 */
7	
8	export type { OutMessage } from './message.ts';
9	
10	export { memoryTransport } from './transport.ts';
11	export type { Transport } from './transport.ts';
12	
13	export { sendNotification } from './sender.ts';
