1	/**
2	 * Очередь исходящих.
3	 *
4	 * Уведомления накапливаются и уходят разом по `drain`. Очередь — объект, а не состояние
5	 * модуля: у каждого вызывающего своя, и тесты не делят одну очередь через общий импорт.
6	 * Порядок отдачи — порядок постановки: `drain` отправляет то, что накопилось, и ничего
7	 * не переставляет.
8	 */
9	
10	import { logEvent } from './log.ts';
11	import type { OutMessage } from './message.ts';
12	import { sendNotification } from './sender.ts';
13	import type { Transport } from './transport.ts';
14	
15	export interface Outbox {
16	  /** Поставить уведомление в очередь. Ничего не отправляет. */
17	  enqueue(msg: OutMessage): void;
18	  /** Отправить всё накопленное через транспорт. Возвращает id отправок в порядке отправки; очередь пустеет. */
19	  drain(transport: Transport): string[];
20	  /** Сколько уведомлений ждёт отправки. */
21	  pending(): number;
22	}
23	
24	export function createOutbox(): Outbox {
25	  const queue: OutMessage[] = [];
26	  return {
27	    enqueue(msg: OutMessage): void {
28	      queue.push(msg);
29	    },
30	    drain(transport: Transport): string[] {
31	      const ids: string[] = [];
32	      for (const msg of queue) ids.push(sendNotification(transport, msg).id);
33	      queue.length = 0;
34	      // В журнал идёт счётчик, не адресаты: см. README, «персональные данные не пишутся».
35	      logEvent(`отправлено из очереди: ${ids.length}`);
36	      return ids;
37	    },
38	    pending(): number {
39	      return queue.length;
40	    },
41	  };
42	}
43

1	/**
2	 * Журнал событий в памяти.
3	 *
4	 * Сюда пишут СОБЫТИЯ, а не данные. Адресат, телефон и текст уведомления — персональные
5	 * данные, и в журнале их нет по политике (README, «Соглашения»): журнал читают люди, у
6	 * которых нет права видеть, кому и что мы отправили. Отсюда и форма записи — строка без
7	 * структуры: положить в неё объект целиком «на всякий случай» нельзя по типу.
8	 *
9	 * В памяти, а не в файле: у стенда нет приёмника логов, а тестам нужен доступ к записям.
10	 */
11	
12	const entries: string[] = [];
13	
14	/** Записать событие. */
15	export function logEvent(entry: string): void {
16	  entries.push(entry);
17	}
18	
19	/** Снимок журнала. Копия, а не сам массив: журнал меняется только через logEvent. */
20	export function events(): readonly string[] {
21	  return entries.slice();
22	}
23	
24	/** Очистить журнал — для тестов, чтобы записи одного не читались в другом. */
25	export function resetLog(): void {
26	  entries.length = 0;
27	}
28

1	/**
2	 * Транспорт.
3	 *
4	 * Сети здесь нет: транспорт — интерфейс, а единственная реализация в репозитории —
5	 * памятная, для тестов. Транспорт доставляет и выдаёт id отправки; правила отправки
6	 * (кому, когда, сколько раз) — не его забота, они лежат выше, у отправителя и очереди.
7	 */
8	
9	import type { OutMessage } from './message.ts';
10	
11	export interface Transport {
12	  /** Доставить сообщение. Возвращает id отправки, присвоенный транспортом. */
13	  send(msg: OutMessage): string;
14	}
15	
16	/**
17	 * Памятный транспорт — стенд для тестов: всё «отправленное» лежит в `sent`, id выдаются
18	 * подряд от единицы. Счётчик свой на каждый экземпляр, чтобы тесты не зависели от порядка
19	 * запуска друг друга.
20	 */
21	export function memoryTransport(): Transport & { sent: OutMessage[] } {
22	  const sent: OutMessage[] = [];
23	  let nextId = 1;
24	  return {
25	    sent,
26	    send(msg: OutMessage): string {
27	      sent.push(msg);
28	      const id = `mem-${nextId}`;
29	      nextId += 1;
30	      return id;
31	    },
32	  };
33	}
34

1	/**
2	 * Тесты очереди.
3	 *
4	 * Уведомления здесь без приоритетов и одному адресату не идут подряд: это покрытие
5	 * «enqueue → drain отдаёт всё в порядке постановки», и любое будущее правило очереди
6	 * обязано оставить этот случай как есть.
7	 */
8	
9	import { deepStrictEqual, strictEqual } from 'node:assert/strict';
10	import { describe, it } from 'node:test';
11	
12	import { createOutbox, memoryTransport } from '../src/index.ts';
13	
14	describe('очередь исходящих', () => {
15	  it('enqueue накапливает, ничего не отправляя', () => {
16	    const box = createOutbox();
17	    box.enqueue({ to: 'anna@example.ru', text: 'Заказ собран' });
18	    box.enqueue({ to: 'boris@example.ru', text: 'Заказ выдан' });
19	    strictEqual(box.pending(), 2);
20	  });
21	
22	  it('drain отправляет накопленное в порядке постановки и опустошает очередь', () => {
23	    const box = createOutbox();
24	    const t = memoryTransport();
25	    box.enqueue({ to: 'anna@example.ru', text: 'Заказ собран' });
26	    box.enqueue({ to: 'boris@example.ru', text: 'Заказ выдан' });
27	    const ids = box.drain(t);
28	    deepStrictEqual(ids, ['mem-1', 'mem-2']);
29	    deepStrictEqual(
30	      t.sent.map((m) => m.to),
31	      ['anna@example.ru', 'boris@example.ru'],
32	    );
33	    strictEqual(box.pending(), 0);
34	  });
35	
36	  it('drain пустой очереди ничего не отправляет', () => {
37	    const box = createOutbox();
38	    const t = memoryTransport();
39	    deepStrictEqual(box.drain(t), []);
40	    strictEqual(t.sent.length, 0);
41	  });
42	});
