1	/**
2	 * Отправитель.
3	 *
4	 * Тонкая обёртка над транспортом: одна точка, через которую уходит каждое уведомление.
5	 * Она нужна не ради строки кода, а ради места — правила отправки, когда появятся, встанут
6	 * сюда, а не размажутся по вызывающим.
7	 */
8	
9	import type { OutMessage } from './message.ts';
10	import type { Transport } from './transport.ts';
11	
12	/** Отправить одно уведомление. Возвращает id отправки, выданный транспортом. */
13	export function sendNotification(transport: Transport, msg: OutMessage): { id: string } {
14	  return { id: transport.send(msg) };
15	}
16

1	/**
2	 * Публичный контракт пакета.
3	 *
4	 * Всё, что вызывают снаружи, проходит через этот файл. Внутренние модули друг на друга
5	 * ссылаются напрямую, но потребитель знает только отсюда.
6	 */
7	
8	export type { OutMessage } from './message.ts';
9	
10	export { memoryTransport } from './transport.ts';
11	export type { Transport } from './transport.ts';
12	
13	export { sendNotification } from './sender.ts';
14	
15	export { createOutbox } from './outbox.ts';
16	export type { Outbox } from './outbox.ts';
17	
18	export { events, logEvent, resetLog } from './log.ts';
19

1	/**
2	 * Тесты отправителя.
3	 *
4	 * Отправка без опций: уведомление доходит до транспорта как есть, id — тот, что выдал
5	 * транспорт. Вызовы здесь намеренно без ключей, приоритетов и прочих опций — это контракт
6	 * «как было», и он обязан остаться законным.
7	 */
8	
9	import { deepStrictEqual, strictEqual } from 'node:assert/strict';
10	import { describe, it } from 'node:test';
11	
12	import { memoryTransport, sendNotification } from '../src/index.ts';
13	
14	describe('отправитель', () => {
15	  it('уведомление доходит до транспорта как есть', () => {
16	    const t = memoryTransport();
17	    const msg = { to: 'anna@example.ru', text: 'Заказ собран' };
18	    sendNotification(t, msg);
19	    strictEqual(t.sent.length, 1);
20	    deepStrictEqual(t.sent[0], msg);
21	  });
22	
23	  it('id отправки — тот, что выдал транспорт', () => {
24	    const t = memoryTransport();
25	    const first = sendNotification(t, { to: 'anna@example.ru', text: 'Заказ собран' });
26	    const second = sendNotification(t, { to: 'boris@example.ru', text: 'Заказ выдан', phone: '+79001112233' });
27	    strictEqual(first.id, 'mem-1');
28	    strictEqual(second.id, 'mem-2');
29	    strictEqual(t.sent.length, 2);
30	  });
31	});
